package org.transittr.tests;
import android.app.*;import android.os.*;import java.lang.reflect.*;import java.security.cert.*;
/** Check hostname boundaries and rejection of a valid but untrusted self-signed server certificate. */
public final class TlsCheck extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle b=new Bundle();boolean pass=false;try{Class<?> type=getTargetContext().getClassLoader().loadClass("org.transittr.TlsSecurity");type.getMethod("init",android.content.Context.class).invoke(null,getTargetContext());Field extra=type.getDeclaredField("extra");extra.setAccessible(true);javax.net.ssl.X509TrustManager manager=(javax.net.ssl.X509TrustManager)extra.get(null);if(manager==null||manager.getAcceptedIssuers().length<3)throw new AssertionError("Bundled CA roots not loaded");Method match=type.getDeclaredMethod("dnsMatch",String.class,String.class);match.setAccessible(true);String[][] cases={{"api.example.com","*.example.com","true"},{"a.b.example.com","*.example.com","false"},{"badexample.com","*.example.com","false"},{"example.com","*.com","false"},{"api.example.com","api.example.com","true"}};for(String[] c:cases)if(!String.valueOf(match.invoke(null,c[0],c[1])).equals(c[2]))throw new AssertionError("hostname boundary");java.io.InputStream in=getContext().getAssets().open("untrusted-server.pem");X509Certificate certificate;try{certificate=(X509Certificate)CertificateFactory.getInstance("X.509").generateCertificate(in);}finally{in.close();}certificate.checkValidity();boolean rejected=false;try{type.getMethod("verify",String.class,X509Certificate[].class).invoke(null,"example.com",new X509Certificate[]{certificate});}catch(InvocationTargetException expected){rejected=expected.getCause() instanceof CertificateException;}if(!rejected)throw new AssertionError("untrusted self-signed certificate accepted");pass=true;b.putString("stream","PASS Android "+Build.VERSION.RELEASE+"; TLS_CHAIN_VALIDATION=true; HOSTNAME_BOUNDARIES=true; UNTRUSTED_SELF_SIGNED_REJECTED=true\n");}catch(Throwable e){java.io.StringWriter w=new java.io.StringWriter();e.printStackTrace(new java.io.PrintWriter(w));b.putString("stream","FAIL TLS\n"+w);}finish(pass?Activity.RESULT_OK:Activity.RESULT_CANCELED,b);}
}
